items.push(make('documentation-shell','Documentation shell','templates','A readable documentation layout with working navigation, examples, and code copying.',['Template','Interactive'],
`<div class="demo docs-shell"><nav><b>FORM / DOCS</b><span>⌘ K &nbsp; / &nbsp; v1.0</span></nav><div class="docs-layout"><aside><span>START HERE</span><button class="active" data-doc="0">Introduction</button><button data-doc="1">Quick start</button><button data-doc="2">Customization</button><div><small>BUILT WITH INTENTION</small><b>✳</b></div></aside><main><span class="docs-breadcrumb">Getting started / Introduction</span><h1>A little structure.<br>A lot of possibility.</h1><p class="docs-copy">A considered foundation for your next idea. Pick the pieces you need and make something entirely your own.</p><div class="docs-callout"><span>↗</span><p>Everything is yours to adjust. Start simple and follow your curiosity.</p></div><div class="docs-code"><button>Copy</button><code>npx create-something-good</code></div><footer><span>CONTINUE EXPLORING</span><button class="docs-next">Quick start →</button></footer></main></div></div>`,
`.docs-shell{max-width:510px;background:#1b1b1b;border:1px solid #434343;border-radius:9px;overflow:hidden}.docs-shell>nav{display:flex;align-items:center;justify-content:space-between;padding:12px 18px;border-bottom:1px solid #3b3b3b;font-size:5px;color:#7a7a7a}.docs-shell nav b{font-size:8px;font-weight:500;color:#c5c5c5}.docs-layout{display:grid;grid-template-columns:112px 1fr}.docs-layout aside{padding:18px 10px;border-right:1px solid #3b3b3b;display:flex;flex-direction:column;background:#1f1f1f}.docs-layout aside>span{font-size:4px;letter-spacing:.08em;color:#767676;padding:0 7px 10px}.docs-layout aside>button{background:none;color:#949494;font-size:6px;padding:7px;text-align:left;border-radius:4px;margin-bottom:2px}.docs-layout aside>button.active{background:#404040;color:#dbdbdb}.docs-layout aside>div{margin:auto 7px 0;padding-top:20px}.docs-layout aside small{font-size:3px;letter-spacing:.06em;color:#6e6e6e}.docs-layout aside b{font-size:29px;display:block;color:#8b8b8b;margin-top:5px;font-weight:400}.docs-layout main{padding:23px}.docs-breadcrumb{display:block;color:#757575;font-size:4px}.docs-layout h1{font-size:clamp(19px,4.8vw,29px);letter-spacing:-.05em;font-weight:450;line-height:1.1;margin:13px 0 10px}.docs-copy{font-size:7px;line-height:1.8;color:#a0a0a0}.docs-callout{display:flex;gap:8px;align-items:center;background:#343434;border:1px solid #535353;border-radius:4px;padding:9px;margin:15px 0}.docs-callout>span{font-size:13px;color:var(--lime)}.docs-callout p{font-size:6px;line-height:1.7;color:#b1b1b1}.docs-code{position:relative;border:1px solid #414141;background:#151515;border-radius:4px;padding:13px 10px}.docs-code code{font-family:ui-monospace,monospace;color:#b7b7b7;font-size:6px}.docs-code button{position:absolute;right:7px;top:5px;background:none;color:#7b7b7b;font-size:4px!important;padding:2px}.docs-layout main>footer{display:flex;align-items:center;justify-content:space-between;padding-top:16px;margin-top:15px;border-top:1px solid #3d3d3d}.docs-layout main footer>span{font-size:3px;letter-spacing:.06em;color:#757575}.docs-next{background:none;color:#c6c6c6;padding:0;font-size:6px!important}@media(max-width:360px){.docs-layout{grid-template-columns:77px 1fr}.docs-layout aside{padding:13px 6px}.docs-layout aside>button{font-size:5px;padding:6px}.docs-layout main{padding:15px}.docs-layout h1{font-size:19px;margin:10px 0 8px}.docs-copy{font-size:5px}.docs-callout{margin:10px 0;padding:6px;gap:5px}.docs-callout p{font-size:4px}.docs-code{padding:10px 7px}.docs-code code{font-size:4px}.docs-layout main>footer{margin-top:10px;padding-top:10px}.docs-next{font-size:5px!important}.docs-layout aside b{font-size:23px}}`,
`const docs=[['Introduction','A little structure.<br>A lot of possibility.','A considered foundation for your next idea. Pick the pieces you need and make something entirely your own.','Everything is yours to adjust. Start simple and follow your curiosity.','npx create-something-good'],['Quick start','Make your<br>first move.','Create a new project, add your favorite component, and explore the details. A good beginning is a small one.','Copy the command below into your terminal. Then follow the prompts to get started.','npm run start'],['Customization','Make it feel<br>like your own.','Adjust colors, spacing, typography, and motion. A few thoughtful details can change the whole experience.','Use CSS variables to keep your visual language consistent across every component.',':root { --accent: #ececec; }']];let current=0;function render(){const d=docs[current];document.querySelector('.docs-breadcrumb').textContent='Getting started / '+d[0];document.querySelector('.docs-layout h1').innerHTML=d[1];document.querySelector('.docs-copy').textContent=d[2];document.querySelector('.docs-callout p').textContent=d[3];document.querySelector('.docs-code code').textContent=d[4];document.querySelector('.docs-next').textContent=docs[(current+1)%3][0]+' →';document.querySelectorAll('.docs-layout aside>button').forEach((b,i)=>b.classList.toggle('active',i===current))}document.querySelectorAll('.docs-layout aside>button').forEach(b=>b.onclick=()=>{current=Number(b.dataset.doc);render()});document.querySelector('.docs-next').onclick=()=>{current=(current+1)%3;render()};document.querySelector('.docs-code button').onclick=async e=>{try{await navigator.clipboard.writeText(docs[current][4]);e.target.textContent='Copied ✓'}catch{e.target.textContent='Select code';const r=document.createRange();r.selectNodeContents(document.querySelector('.docs-code code'));const s=window.getSelection();s.removeAllRanges();s.addRange(r)}setTimeout(()=>e.target.textContent='Copy',1200)};`));

items.push(make('minimal-checkout','Minimal checkout','templates','A complete order form with quantity controls, dynamic totals, and a demo confirmation.',['Template','Interactive'],
`<div class="demo checkout"><header><b>COMMON OBJECTS®</b><span>Thoughtful things, on their way. ↗</span></header><div class="checkout-layout"><form><span class="checkout-label">ONE MORE LITTLE STEP</span><h2>Good things,<br>coming your way.</h2><label>Email address<input type="email" required placeholder="you@example.com" autocomplete="email"></label><div class="checkout-fields"><label>First name<input required placeholder="Alex" autocomplete="given-name"></label><label>Last name<input required placeholder="Common" autocomplete="family-name"></label></div><label>Shipping address<input required placeholder="A place to call home" autocomplete="street-address"></label><button type="submit" class="place-order">Complete demo order ↗</button><small class="checkout-status" role="status">Demo checkout. No payment or data collected.</small></form><aside><span class="checkout-label">YOUR GOOD THINGS</span><div class="checkout-product"><div class="checkout-cup"><i></i></div><p>Everyday cup<small>Sage / handmade ceramic</small><b>$28</b></p></div><div class="quantity-control"><span>Quantity</span><button class="quantity-minus" aria-label="Decrease quantity">−</button><b>1</b><button class="quantity-plus" aria-label="Increase quantity">+</button></div><div class="order-lines"><p>Subtotal <span class="subtotal">$28</span></p><p>Shipping <span>$6</span></p><p class="order-total">Total <strong>$34</strong></p></div><span class="checkout-note">A SMALL COLLECTION.<br>MADE WITH CARE.</span></aside></div></div>`,
`.checkout{max-width:510px;background:#1e1e1e;border:1px solid #444444;border-radius:9px;overflow:hidden}.checkout>header{display:flex;align-items:center;justify-content:space-between;padding:12px 18px;border-bottom:1px solid #3b3b3b;font-size:5px;color:#797979}.checkout header>b{font-size:7px;color:#c0c0c0}.checkout header>span{font-size:4px}.checkout-layout{display:grid;grid-template-columns:1.3fr 1fr}.checkout form{padding:21px}.checkout-label{font-size:4px;letter-spacing:.1em;color:#7a7a7a}.checkout h2{font-size:clamp(20px,5.2vw,30px);line-height:1.03;font-weight:450;letter-spacing:-.05em;margin:10px 0 17px}.checkout label{font-size:5px;display:block;color:#b0b0b0;margin-bottom:9px}.checkout input{margin-top:4px;display:block;background:#2c2c2c;border:1px solid #4f4f4f;width:100%;padding:7px 8px;color:#e1e1e1;border-radius:4px;font-size:6px}.checkout input::placeholder{color:#6e6e6e}.checkout-fields{display:flex;gap:7px}.checkout-fields label{width:50%}.place-order{background:var(--lime);color:#3d3d3d;font-size:6px!important;padding:9px;width:100%;border-radius:4px;margin-top:2px}.checkout-status{display:block;text-align:center;font-size:4px;color:#707070;margin-top:7px;line-height:1.6}.checkout aside{padding:23px 18px;background:#2c2c2c;border-left:1px solid #474747}.checkout-product{display:flex;gap:11px;align-items:center;margin:22px 0 18px}.checkout-cup{position:relative;width:37px;height:37px;background:linear-gradient(90deg,#848484,#afafaf 40%,#8e8e8e);border-radius:3px 3px 13px 13px;flex:none}.checkout-cup:before{content:'';position:absolute;left:0;top:-2px;width:37px;height:6px;border-radius:50%;background:#747474;border:2px solid #a9a9a9}.checkout-cup i{position:absolute;right:-10px;top:4px;width:15px;height:23px;border:4px solid #959595;border-left:0;border-radius:0 50% 50% 0}.checkout-product p{font-size:7px}.checkout-product small{display:block;font-size:4px;color:#8c8c8c;margin-top:3px}.checkout-product b{display:block;font-size:7px;color:#bababa;margin-top:5px;font-weight:450}.quantity-control{display:flex;align-items:center;gap:8px;font-size:6px;color:#a7a7a7}.quantity-control>span{margin-right:auto;font-size:5px}.quantity-control button{height:16px;width:16px;border:1px solid #5e5e5e!important;background:#404040;color:#c0c0c0;font-size:8px!important;border-radius:3px;padding:0}.quantity-control b{font-size:6px;font-weight:450}.order-lines{margin-top:20px;padding-top:12px;border-top:1px solid #4e4e4e}.order-lines p{display:flex;justify-content:space-between;font-size:5px;color:#969696;margin-bottom:8px}.order-lines .order-total{font-size:7px;color:#d8d8d8;border-top:1px solid #4e4e4e;margin-top:12px;padding-top:11px}.order-total strong{font-weight:450;font-size:15px}.checkout-note{display:block;font-size:4px;letter-spacing:.07em;color:#6e6e6e;margin-top:22px;line-height:1.5}@media(max-width:360px){.checkout>header{padding:8px 12px}.checkout header>span{font-size:3px}.checkout form{padding:14px}.checkout aside{padding:16px 11px}.checkout h2{font-size:20px;margin:8px 0 12px}.checkout input{padding:5px 6px;font-size:5px}.checkout label{font-size:4px;margin-bottom:6px}.checkout-status{font-size:3px}.checkout-product{margin:17px 0 14px;gap:7px}.checkout-cup{transform:scale(.8);margin-left:-4px;margin-right:-4px}.checkout-product p{font-size:5px}.checkout-product small{font-size:3px}.order-lines{margin-top:14px;padding-top:9px}.checkout-note{margin-top:15px;font-size:3px}.order-lines p{font-size:4px}.order-total strong{font-size:12px}}`,
`let quantity=1;function update(){document.querySelector('.quantity-control b').textContent=quantity;document.querySelector('.subtotal').textContent='$'+quantity*28;document.querySelector('.order-total strong').textContent='$'+(quantity*28+6);document.querySelector('.quantity-minus').disabled=quantity===1}document.querySelector('.quantity-minus').onclick=()=>{quantity=Math.max(1,quantity-1);update()};document.querySelector('.quantity-plus').onclick=()=>{quantity=Math.min(9,quantity+1);update()};document.querySelector('form').onsubmit=e=>{e.preventDefault();document.querySelector('.checkout-status').textContent='✓ Your demo order is confirmed. No data was sent.';document.querySelector('.place-order').textContent='Good things are on their way ✓'};update();`,true));

items.push(make('creative-studio','Creative studio','templates','A confident studio website concept with a working work/about navigation.',['Template','Interactive'],
`<div class="demo creative-studio"><nav><b>OTHER<br>FORM®</b><div><button class="active" data-view="work">Our work</button><button data-view="about">The studio</button></div><span>LET'S MAKE SOMETHING ↗</span></nav><div class="studio-view work-view"><header><span>INDEPENDENT DESIGN & DIGITAL CRAFT</span><h1>Good ideas.<br><em>Other forms.</em></h1><p>We turn a little curiosity<br>into something worth feeling.</p></header><div class="studio-projects"><div class="studio-project-one"><span>LESS<br>BUT<br><em>better.</em></span><small>FORM & FEELING / BRAND</small></div><div class="studio-project-two"><i></i><span>COMMON<br>GROUND</span><small>A NEW PERSPECTIVE / DIGITAL</small></div></div></div><div class="studio-view about-view" hidden><span class="studio-about-label">A SMALL STUDIO. A LOT OF POSSIBILITY.</span><h2>Curiosity is<br>our common<br><em>ground.</em></h2><p>We are an independent creative practice exploring the space between strategy, design, and digital craft.</p><div class="studio-capabilities"><span>01 / Brand strategy</span><span>02 / Visual identity</span><span>03 / Digital experiences</span></div></div><footer><span>GOOD WORK IS A CONVERSATION.</span><span>EST. 2024 / EVERYWHERE</span></footer></div>`,
`.creative-studio{max-width:510px;background:#e1e1e1;color:#3d3d3d;padding:clamp(12px,3vw,20px);border-radius:5px}.creative-studio nav{display:flex;align-items:center;justify-content:space-between;padding-bottom:12px;border-bottom:1px solid #bfbfbf;gap:10px}.creative-studio nav>b{font-size:10px;line-height:.85;letter-spacing:-.05em;font-weight:600}.creative-studio nav>div{display:flex;gap:9px}.creative-studio nav button{background:none;color:#9a9a9a;font-size:5px;padding:3px 0}.creative-studio nav button.active{color:#505050;border-bottom:1px solid #828282}.creative-studio nav>span{font-size:4px;letter-spacing:.03em;color:#999999}.creative-studio .work-view>header{position:relative;padding:18px 0}.creative-studio header>span{font-size:4px;letter-spacing:.1em;color:#989898}.creative-studio h1{font-size:clamp(31px,8vw,48px);line-height:.91;letter-spacing:-.06em;font-weight:450;margin-top:11px}.creative-studio h1 em{font-family:Georgia,serif;font-weight:400}.creative-studio header>p{position:absolute;right:0;bottom:20px;font-size:6px;line-height:1.7;color:#999999}.studio-projects{display:grid;grid-template-columns:1fr 1fr;gap:9px}.studio-projects>div{height:clamp(77px,20vw,120px);position:relative;overflow:hidden;padding:12px 15px}.studio-project-one{background:#939393;color:#ebebeb}.studio-project-one>span{font-size:clamp(21px,5.6vw,33px);line-height:.85;letter-spacing:-.05em;display:block;transform:rotate(-8deg)}.studio-project-one em{font-family:Georgia,serif;font-weight:400}.studio-projects small{position:absolute;bottom:9px;left:15px;font-size:3px;letter-spacing:.05em;opacity:.6}.studio-project-two{background:#454545;color:#e2e2e2;display:flex;align-items:center}.studio-project-two i{position:absolute;width:130px;height:130px;right:-30px;top:-40px;background:#909090;border-radius:50%}.studio-project-two>span{font-size:clamp(16px,4.2vw,25px);letter-spacing:-.04em;line-height:1;position:relative;z-index:1;font-weight:450}.creative-studio>footer{display:flex;justify-content:space-between;margin-top:11px;border-top:1px solid #bfbfbf;padding-top:8px;font-size:4px;letter-spacing:.03em;color:#9d9d9d}.studio-view[hidden]{display:none}.about-view{position:relative;padding:24px 0 18px;min-height:246px}.studio-about-label{font-size:4px;letter-spacing:.1em;color:#9c9c9c}.about-view h2{font-size:clamp(32px,8vw,49px);font-weight:450;line-height:.9;letter-spacing:-.06em;margin:14px 0}.about-view h2 em{font-family:Georgia,serif;font-weight:400}.about-view>p{font-size:7px;line-height:1.8;max-width:170px;color:#989898;position:absolute;right:0;top:80px;width:40%}.studio-capabilities{display:flex;gap:15px;font-size:5px;color:#949494;border-top:1px solid #c4c4c4;padding-top:11px;margin-top:15px}@media(max-width:360px){.creative-studio nav>b{font-size:8px}.creative-studio nav>span{font-size:3px}.creative-studio .work-view>header{padding:14px 0}.creative-studio h1{font-size:31px}.creative-studio header>p{font-size:4px;bottom:15px}.studio-projects>div{padding:10px}.studio-projects small{left:10px;bottom:6px;font-size:3px}.about-view{min-height:185px;padding:18px 0 12px}.about-view h2{font-size:33px}.about-view>p{font-size:5px;top:60px}.studio-capabilities{font-size:3px;gap:10px;padding-top:8px}}`,
`document.querySelectorAll('.creative-studio nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.creative-studio nav button').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('.work-view').hidden=b.dataset.view!=='work';document.querySelector('.about-view').hidden=b.dataset.view!=='about'});`));
export default items;
